INSERT INTO public.legends VALUES
('lemmy-hendrix','Lemmy Kilmister','Basso','Il roadie di Jimi Hendrix','Prima di fondare i Motörhead, nel 1967 Lemmy lavorò come roadie per la Jimi Hendrix Experience. Nella sua autobiografia racconta che tra i suoi compiti c''era anche procurare l''acido a Hendrix.',1967,21),
('hetfield-fire','James Hetfield','Voce e chitarra','Il frontman che prese fuoco','L''8 agosto 1992, a Montréal, durante "Fade to Black" Hetfield finì dentro la fiammata di un effetto pirotecnico: ustioni gravi a braccio, mano e viso. Per settimane un altro chitarrista suonò la ritmica al posto suo mentre lui cantava.',1992,22),
('hetfield-skate','James Hetfield','Voce e chitarra','Lo skateboard proibito','Nel 1986 Hetfield si ruppe il polso cadendo dallo skateboard durante il tour di "Master of Puppets". Per alcune date la chitarra ritmica la suonò il loro tecnico John Marshall. Da allora nei contratti della band lo skate fu vietato.',1986,23),
('ozzy-bat','Ozzy Osbourne','Voce','Il pipistrello','Il 20 gennaio 1982 a Des Moines un fan lanciò sul palco un pipistrello. Ozzy, convinto che fosse di gomma, gli staccò la testa con un morso. Era vero: dovette fare le iniezioni contro la rabbia.',1982,24),
('alice-chicken','Alice Cooper','Voce','Il pollo di Toronto','Nel 1969 a un festival di Toronto qualcuno lanciò un pollo vivo sul palco. Alice Cooper, pensando che sapesse volare, lo rilanciò verso il pubblico, che lo fece a pezzi. Il giorno dopo i giornali scrissero che l''aveva ucciso lui, e la sua fama da "cattivo" esplose.',1969,25),
('vanhalen-mms','Van Halen','Band','Niente M&M''s marroni','Nel contratto dei concerti i Van Halen chiedevano una ciotola di M&M''s senza quelli marroni. Non era un capriccio: se li trovavano, capivano che gli organizzatori non avevano letto bene il contratto, comprese le regole di sicurezza del palco.',1982,26),
('moon-explosion','Keith Moon','Batteria','La grancassa esplosa in TV','Nel 1967 al "Smothers Brothers Comedy Hour" Keith Moon riempì la grancassa con troppo esplosivo. Lo scoppio lo ferì e fece bruciare i capelli a Pete Townshend, che disse di averne avuto danni all''udito per sempre.',1967,27),
('moon-halpin','Keith Moon','Batteria','Il fan che salì sul palco','Nel 1973 a San Francisco Keith Moon svenne durante un concerto degli Who. Townshend chiese al pubblico se qualcuno sapeva suonare la batteria: il diciannovenne Scot Halpin salì e finì il concerto con la band.',1973,28),
('townshend-smash','Pete Townshend','Chitarra','La prima chitarra distrutta','Nel 1964, al Railway Tavern di Londra, Townshend ruppe per sbaglio il manico della chitarra contro il soffitto basso del locale. Per non sembrare impacciato la fece a pezzi del tutto: il pubblico impazzì e diventò il suo marchio.',1964,29),
('hendrix-monterey','Jimi Hendrix','Chitarra','La chitarra in fiamme','Al Monterey Pop Festival del 1967 Hendrix si inginocchiò davanti alla sua Stratocaster, la cosparse di liquido per accendini e le diede fuoco. È una delle immagini più famose della storia del rock.',1967,30),
('keith-ashes','Keith Richards','Chitarra','Le ceneri del padre','Nel 2007 Keith Richards raccontò in un''intervista di aver "sniffato" un po'' delle ceneri di suo padre. Il suo manager provò a dire che era uno scherzo, ma Keith ha confermato la storia anche nella sua autobiografia, "Life".',2007,31),
('beatles-rooftop','The Beatles','Band','L''ultimo concerto sul tetto','Il 30 gennaio 1969 i Beatles suonarono a sorpresa sul tetto della Apple a Londra. Dopo circa 40 minuti arrivò la polizia per il rumore: fu la loro ultima esibizione dal vivo.',1969,32),
('cash-folsom','Johnny Cash','Voce e chitarra','Il concerto in prigione','Nel 1968 Johnny Cash registrò un disco dal vivo nel carcere di Folsom, in California. "At Folsom Prison" fu un successo enorme e rilanciò la sua carriera.',1968,33),
('elvis-waist','Elvis Presley','Voce','Ripreso solo dalla vita in su','Nel 1957, alla sua terza apparizione all''"Ed Sullivan Show", Elvis fu inquadrato solo dalla vita in su: i suoi movimenti di bacino erano considerati troppo scandalosi per la TV.',1957,34),
('collins-live-aid','Phil Collins','Batteria','Due continenti in un giorno','Il 13 luglio 1985 Phil Collins suonò al Live Aid di Londra, poi prese il Concorde e suonò anche al Live Aid di Philadelphia, lo stesso giorno.',1985,35),
('metallica-antarctica','Metallica','Band','Un concerto in Antartide','Nel 2013 i Metallica suonarono in Antartide per un piccolo pubblico, con il suono mandato solo nelle cuffie per non disturbare l''ambiente. Così suonarono in tutti e sette i continenti in un anno: un record da Guinness.',2013,36),
('robert-johnson','Robert Johnson','Chitarra','Il patto all''incrocio','Secondo la leggenda il bluesman Robert Johnson vendette l''anima al diavolo a un incrocio per diventare un chitarrista straordinario. È un mito, ma ha ispirato canzoni e film per quasi cent''anni.',1936,37),
('paganini-devil','Niccolò Paganini','Violino','Il violinista del diavolo','Paganini era così virtuoso che ai suoi tempi si diceva avesse fatto un patto con il diavolo. Lui non smentiva: la voce aiutava a riempire i teatri.',1820,38)
